import React, { useState, useEffect } from 'react';
import axios from 'axios';

function AdminDashboard({ onLogout }) {
  const [activeView, setActiveView] = useState('overview');
  const [events, setEvents] = useState([]);
  const [volunteers, setVolunteers] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  // Form states
  const [eventForm, setEventForm] = useState({
    name: '',
    date: '',
    location: '',
    description: ''
  });

  const [volunteerForm, setVolunteerForm] = useState({
    name: '',
    email: '',
    phone: '',
    skills: ''
  });

  const [assignmentForm, setAssignmentForm] = useState({
    eventId: '',
    volunteerId: '',
    duty: '',
    schedule: ''
  });

  useEffect(() => {
    fetchAllData();
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      const [eventsRes, volunteersRes, assignmentsRes, statsRes] = await Promise.allSettled([
        axios.get('/api/events'),
        axios.get('/api/volunteers'),
        axios.get('/api/assignments'),
        axios.get('/api/assignments/stats')
      ]);

      // Handle events response
      if (eventsRes.status === 'fulfilled' && eventsRes.value.data.success) {
        setEvents(eventsRes.value.data.data);
      } else if (eventsRes.status === 'rejected') {
        console.error('Error fetching events:', eventsRes.reason);
      }

      // Handle volunteers response
      if (volunteersRes.status === 'fulfilled' && volunteersRes.value.data.success) {
        setVolunteers(volunteersRes.value.data.data);
      } else if (volunteersRes.status === 'rejected') {
        console.error('Error fetching volunteers:', volunteersRes.reason);
      }

      // Handle assignments response
      if (assignmentsRes.status === 'fulfilled' && assignmentsRes.value.data.success) {
        setAssignments(assignmentsRes.value.data.data);
      } else if (assignmentsRes.status === 'rejected') {
        console.error('Error fetching assignments:', assignmentsRes.reason);
      }

      // Handle stats response (optional - don't fail if stats fail)
      if (statsRes.status === 'fulfilled' && statsRes.value.data.success) {
        setStats(statsRes.value.data.data);
      } else if (statsRes.status === 'rejected') {
        console.error('Error fetching stats:', statsRes.reason);
        // Set default stats if stats endpoint fails
        setStats({ total: 0, pending: 0, inProgress: 0, completed: 0, cancelled: 0 });
      }
    } catch (error) {
      console.error('Unexpected error fetching data:', error);
      showMessage('Error loading some data', 'error');
    } finally {
      setLoading(false);
    }
  };

  const showMessage = (msg, type = 'success') => {
    setMessage({ text: msg, type });
    setTimeout(() => setMessage(''), 3000);
  };

  // Event Handlers
  const handleCreateEvent = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post('/api/events', eventForm);
      if (response.data.success) {
        showMessage('Event created successfully!');
        setEventForm({ name: '', date: '', location: '', description: '' });
        fetchAllData();
      }
    } catch (error) {
      showMessage(error.response?.data?.message || 'Error creating event', 'error');
    }
  };

  const handleCreateVolunteer = async (e) => {
    e.preventDefault();
    try {
      const volunteerData = {
        ...volunteerForm,
        skills: volunteerForm.skills.split(',').map(s => s.trim())
      };
      const response = await axios.post('/api/volunteers', volunteerData);
      if (response.data.success) {
        showMessage('Volunteer added successfully!');
        setVolunteerForm({ name: '', email: '', phone: '', skills: '' });
        fetchAllData();
      }
    } catch (error) {
      showMessage(error.response?.data?.message || 'Error adding volunteer', 'error');
    }
  };

  const handleCreateAssignment = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post('/api/assignments', assignmentForm);
      if (response.data.success) {
        showMessage('Assignment created successfully!');
        setAssignmentForm({ eventId: '', volunteerId: '', duty: '', schedule: '' });
        fetchAllData();
      }
    } catch (error) {
      showMessage(error.response?.data?.message || 'Error creating assignment', 'error');
    }
  };

  const handleDeleteEvent = async (id) => {
    if (window.confirm('Are you sure you want to delete this event?')) {
      try {
        await axios.delete(`/api/events/${id}`);
        showMessage('Event deleted successfully!');
        fetchAllData();
      } catch (error) {
        showMessage('Error deleting event', 'error');
      }
    }
  };

  const handleDeleteVolunteer = async (id) => {
    if (window.confirm('Are you sure you want to delete this volunteer?')) {
      try {
        await axios.delete(`/api/volunteers/${id}`);
        showMessage('Volunteer deleted successfully!');
        fetchAllData();
      } catch (error) {
        showMessage('Error deleting volunteer', 'error');
      }
    }
  };

  const handleGenerateReport = async () => {
    try {
      const response = await axios.post('/api/reports/volunteer-report');
      if (response.data.success) {
        showMessage('Report generated successfully!');
        alert(`Report saved to: ${response.data.data.filename}`);
      }
    } catch (error) {
      showMessage('Error generating report', 'error');
    }
  };

  return (
    <div className="dashboard">
      {/* Sidebar */}
      <div className="sidebar">
        <h2>Admin Panel</h2>
        <ul className="nav-menu">
          <li 
            className={`nav-item ${activeView === 'overview' ? 'active' : ''}`}
            onClick={() => setActiveView('overview')}
          >
            📊 Overview
          </li>
          <li 
            className={`nav-item ${activeView === 'events' ? 'active' : ''}`}
            onClick={() => setActiveView('events')}
          >
            📅 Manage Events
          </li>
          <li 
            className={`nav-item ${activeView === 'volunteers' ? 'active' : ''}`}
            onClick={() => setActiveView('volunteers')}
          >
            👥 Manage Volunteers
          </li>
          <li 
            className={`nav-item ${activeView === 'assignments' ? 'active' : ''}`}
            onClick={() => setActiveView('assignments')}
          >
            ✅ Assignments
          </li>
          <li 
            className={`nav-item ${activeView === 'reports' ? 'active' : ''}`}
            onClick={() => setActiveView('reports')}
          >
            📄 Reports
          </li>
        </ul>
        <button className="logout-button" onClick={onLogout}>
          Logout
        </button>
      </div>

      {/* Main Content */}
      <div className="main-content">
        {message && (
          <div className={message.type === 'error' ? 'error-message' : 'success-message'}>
            {message.text}
          </div>
        )}

        {activeView === 'overview' && (
          <div>
            <div className="content-header">
              <h1>Dashboard Overview</h1>
              <p>Welcome to the Event Volunteer Coordination System</p>
            </div>

            {stats && (
              <div className="cards-container">
                <div className="stat-card">
                  <h3>Total Events</h3>
                  <div className="number">{events.length}</div>
                </div>
                <div className="stat-card">
                  <h3>Total Volunteers</h3>
                  <div className="number">{volunteers.length}</div>
                </div>
                <div className="stat-card">
                  <h3>Total Assignments</h3>
                  <div className="number">{stats.total}</div>
                </div>
                <div className="stat-card">
                  <h3>Completed</h3>
                  <div className="number">{stats.completed}</div>
                </div>
              </div>
            )}

            <div className="table-container">
              <h3>Recent Assignments</h3>
              {assignments.length > 0 ? (
                <table>
                  <thead>
                    <tr>
                      <th>Event</th>
                      <th>Volunteer</th>
                      <th>Duty</th>
                      <th>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {assignments.slice(0, 5).map(assignment => (
                      <tr key={assignment._id || assignment.id}>
                        <td>{assignment.eventName}</td>
                        <td>{assignment.volunteerName}</td>
                        <td>{assignment.duty}</td>
                        <td>
                          <span className={`status-badge status-${assignment.status}`}>
                            {assignment.status}
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <div className="empty-state">
                  <h3>No assignments yet</h3>
                  <p>Start by creating events and adding volunteers</p>
                </div>
              )}
            </div>
          </div>
        )}

        {activeView === 'events' && (
          <div>
            <div className="content-header">
              <h1>Manage Events</h1>
              <p>Create and manage events</p>
            </div>

            <div className="form-container">
              <h3>Create New Event</h3>
              <form onSubmit={handleCreateEvent}>
                <div className="form-group">
                  <label>Event Name *</label>
                  <input
                    type="text"
                    value={eventForm.name}
                    onChange={(e) => setEventForm({...eventForm, name: e.target.value})}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Date *</label>
                  <input
                    type="date"
                    value={eventForm.date}
                    onChange={(e) => setEventForm({...eventForm, date: e.target.value})}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Location *</label>
                  <input
                    type="text"
                    value={eventForm.location}
                    onChange={(e) => setEventForm({...eventForm, location: e.target.value})}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Description *</label>
                  <textarea
                    value={eventForm.description}
                    onChange={(e) => setEventForm({...eventForm, description: e.target.value})}
                    required
                  />
                </div>
                <button type="submit" className="btn btn-primary">Create Event</button>
              </form>
            </div>

            <div className="table-container">
              <h3>All Events</h3>
              {events.length > 0 ? (
                <table>
                  <thead>
                    <tr>
                      <th>Name</th>
                      <th>Date</th>
                      <th>Location</th>
                      <th>Status</th>
                      <th>Volunteers</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {events.map(event => {
                      const eventId = event._id || event.id;
                      return (
                      <tr key={eventId}>
                        <td>{event.name}</td>
                        <td>{new Date(event.date).toLocaleDateString()}</td>
                        <td>{event.location}</td>
                        <td>
                          <span className={`status-badge status-${event.status}`}>
                            {event.status}
                          </span>
                        </td>
                        <td>{Array.isArray(event.volunteers) ? event.volunteers.length : 0}</td>
                        <td>
                          <div className="action-buttons">
                            <button 
                              className="btn btn-danger"
                              onClick={() => handleDeleteEvent(eventId)}
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    );})}
                  </tbody>
                </table>
              ) : (
                <div className="empty-state">
                  <h3>No events yet</h3>
                  <p>Create your first event above</p>
                </div>
              )}
            </div>
          </div>
        )}

        {activeView === 'volunteers' && (
          <div>
            <div className="content-header">
              <h1>Manage Volunteers</h1>
              <p>Add and manage volunteers</p>
            </div>

            <div className="form-container">
              <h3>Add New Volunteer</h3>
              <form onSubmit={handleCreateVolunteer}>
                <div className="form-group">
                  <label>Name *</label>
                  <input
                    type="text"
                    value={volunteerForm.name}
                    onChange={(e) => setVolunteerForm({...volunteerForm, name: e.target.value})}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Email *</label>
                  <input
                    type="email"
                    value={volunteerForm.email}
                    onChange={(e) => setVolunteerForm({...volunteerForm, email: e.target.value})}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Phone *</label>
                  <input
                    type="tel"
                    value={volunteerForm.phone}
                    onChange={(e) => setVolunteerForm({...volunteerForm, phone: e.target.value})}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Skills (comma-separated)</label>
                  <input
                    type="text"
                    value={volunteerForm.skills}
                    onChange={(e) => setVolunteerForm({...volunteerForm, skills: e.target.value})}
                    placeholder="e.g. Event Planning, Photography, Catering"
                  />
                </div>
                <button type="submit" className="btn btn-primary">Add Volunteer</button>
              </form>
            </div>

            <div className="table-container">
              <h3>All Volunteers</h3>
              {volunteers.length > 0 ? (
                <table>
                  <thead>
                    <tr>
                      <th>Name</th>
                      <th>Email</th>
                      <th>Phone</th>
                      <th>Skills</th>
                      <th>Events</th>
                      <th>Status</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {volunteers.map(volunteer => {
                      const volunteerId = volunteer._id || volunteer.id;
                      return (
                      <tr key={volunteerId}>
                        <td>{volunteer.name}</td>
                        <td>{volunteer.email}</td>
                        <td>{volunteer.phone}</td>
                        <td>{Array.isArray(volunteer.skills) ? volunteer.skills.join(', ') : ''}</td>
                        <td>{Array.isArray(volunteer.eventsAssigned) ? volunteer.eventsAssigned.length : 0}</td>
                        <td>
                          <span className={`status-badge status-${volunteer.status}`}>
                            {volunteer.status}
                          </span>
                        </td>
                        <td>
                          <div className="action-buttons">
                            <button 
                              className="btn btn-danger"
                              onClick={() => handleDeleteVolunteer(volunteerId)}
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    );})}
                  </tbody>
                </table>
              ) : (
                <div className="empty-state">
                  <h3>No volunteers yet</h3>
                  <p>Add your first volunteer above</p>
                </div>
              )}
            </div>
          </div>
        )}

        {activeView === 'assignments' && (
          <div>
            <div className="content-header">
              <h1>Manage Assignments</h1>
              <p>Assign volunteers to events</p>
            </div>

            <div className="form-container">
              <h3>Create New Assignment</h3>
              <form onSubmit={handleCreateAssignment}>
                <div className="form-group">
                  <label>Select Event *</label>
                  <select
                    value={assignmentForm.eventId}
                    onChange={(e) => setAssignmentForm({...assignmentForm, eventId: e.target.value})}
                    required
                  >
                    <option value="">Choose an event</option>
                    {events.map(event => {
                      const eventId = event._id || event.id;
                      return (
                        <option key={eventId} value={String(eventId)}>
                          {event.name} - {new Date(event.date).toLocaleDateString()}
                        </option>
                      );
                    })}
                  </select>
                </div>
                <div className="form-group">
                  <label>Select Volunteer *</label>
                  <select
                    value={assignmentForm.volunteerId}
                    onChange={(e) => setAssignmentForm({...assignmentForm, volunteerId: e.target.value})}
                    required
                  >
                    <option value="">Choose a volunteer</option>
                    {volunteers.map(volunteer => {
                      const volunteerId = volunteer._id || volunteer.id;
                      return (
                        <option key={volunteerId} value={String(volunteerId)}>
                          {volunteer.name}
                        </option>
                      );
                    })}
                  </select>
                </div>
                <div className="form-group">
                  <label>Duty *</label>
                  <input
                    type="text"
                    value={assignmentForm.duty}
                    onChange={(e) => setAssignmentForm({...assignmentForm, duty: e.target.value})}
                    placeholder="e.g. Registration Desk"
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Schedule *</label>
                  <input
                    type="text"
                    value={assignmentForm.schedule}
                    onChange={(e) => setAssignmentForm({...assignmentForm, schedule: e.target.value})}
                    placeholder="e.g. 9:00 AM - 12:00 PM"
                    required
                  />
                </div>
                <button type="submit" className="btn btn-primary">Create Assignment</button>
              </form>
            </div>

            <div className="table-container">
              <h3>All Assignments</h3>
              {assignments.length > 0 ? (
                <table>
                  <thead>
                    <tr>
                      <th>Event</th>
                      <th>Volunteer</th>
                      <th>Duty</th>
                      <th>Schedule</th>
                      <th>Status</th>
                      <th>Created</th>
                    </tr>
                  </thead>
                  <tbody>
                    {assignments.map(assignment => (
                      <tr key={assignment._id || assignment.id}>
                        <td>{assignment.eventName}</td>
                        <td>{assignment.volunteerName}</td>
                        <td>{assignment.duty}</td>
                        <td>{assignment.schedule}</td>
                        <td>
                          <span className={`status-badge status-${assignment.status}`}>
                            {assignment.status}
                          </span>
                        </td>
                        <td>{assignment.createdAt ? new Date(assignment.createdAt).toLocaleDateString() : '-'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <div className="empty-state">
                  <h3>No assignments yet</h3>
                  <p>Create assignments above</p>
                </div>
              )}
            </div>
          </div>
        )}

        {activeView === 'reports' && (
          <div>
            <div className="content-header">
              <h1>Generate Reports</h1>
              <p>Generate comprehensive volunteer reports</p>
            </div>

            <div className="form-container">
              <h3>Volunteer Report</h3>
              <p>Generate a complete report of all events, volunteers, and assignments. 
                 The report will be saved to the server's data directory.</p>
              <button 
                className="btn btn-success" 
                onClick={handleGenerateReport}
              >
                📄 Generate Report
              </button>
            </div>

            {stats && (
              <div className="table-container">
                <h3>Current Statistics</h3>
                <div className="cards-container">
                  <div className="stat-card">
                    <h3>Total Assignments</h3>
                    <div className="number">{stats.total}</div>
                  </div>
                  <div className="stat-card">
                    <h3>Pending</h3>
                    <div className="number">{stats.pending}</div>
                  </div>
                  <div className="stat-card">
                    <h3>In Progress</h3>
                    <div className="number">{stats.inProgress}</div>
                  </div>
                  <div className="stat-card">
                    <h3>Completed</h3>
                    <div className="number">{stats.completed}</div>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default AdminDashboard;
